import sys, math, json
sys.path.insert(0, '/var/tmp/foundry-work/work/jit-r0-kinetics/s')
import data

def pts(cond):
    out = []
    for sid, c, s, v, unit in data.W:
        if c == cond:
            vv = data.to_uMs(v, unit) * data.DIL_SCALE.get(c, 1.0)
            out.append((s, vv, sid))
    return out

def ssr_km(p, km, vmax=None):
    # profile: best Vmax for given Km (closed form) unless vmax fixed
    f = [s/(km+s) for s, _, _ in p]
    if vmax is None:
        num = sum(v*fi for (_, v, _), fi in zip(p, f)); den = sum(fi*fi for fi in f)
        vm = num/den
    else:
        vm = vmax
    return sum((v - vm*fi)**2 for (_, v, _), fi in zip(p, f)), vm

def golden(fun, a, b, tol=1e-12):
    g = (math.sqrt(5)-1)/2
    c = b - g*(b-a); d = a + g*(b-a)
    fc = fun(c); fd = fun(d)
    while abs(b-a) > tol*(1+abs(a)+abs(b)):
        if fc < fd:
            b, d, fd = d, c, fc; c = b - g*(b-a); fc = fun(c)
        else:
            a, c, fc = c, d, fd; d = a + g*(b-a); fd = fun(d)
    return (a+b)/2

def fit_free(p):
    # log-space search over Km, wide range
    km = math.exp(golden(lambda lk: ssr_km(p, math.exp(lk))[0], math.log(1e-3), math.log(1e5)))
    s, vm = ssr_km(p, km)
    return vm, km, s

def fit_fixed_vmax(p, vmax):
    km = math.exp(golden(lambda lk: ssr_km(p, math.exp(lk), vmax)[0], math.log(1e-3), math.log(1e5)))
    s, _ = ssr_km(p, km, vmax)
    return vmax, km, s

conds = ['C1','C2','C3','C4','C5','C6','C7','C8']
INHIB_REF = {'C4':'C1','C8':'C1','C7':'C2'}
res = {}
for c in conds:
    p = pts(c)
    if c in INHIB_REF:
        vmax = res[INHIB_REF[c]]['vmax']
        vm, km, s = fit_fixed_vmax(p, vmax)
    else:
        vm, km, s = fit_free(p)
    res[c] = {'vmax': vm, 'km': km, 'ssr': s, 'n': len(p)}
    print(c, 'n=%d' % len(p), 'Vmax=%.5f uM/s' % vm, 'Km=%.3f uM' % km, 'SSR=%.3e' % s)

json.dump(res, open('/var/tmp/foundry-work/work/jit-r0-kinetics/s/fit_out.json','w'), indent=1)

